insert into public.products (code, category, name_fr, name_ar, price, slots, description_fr, description_ar, image_url, sort) values
  ('hawas-fire', 'perfume', 'Hawas Fire For Him — Eau de Parfum', 'هواس فاير للرجال — ماء عطر', 13000, 2, 'L''intensité d''un homme : charisme, élégance, séduction. Un mélange raffiné de bois, d''épices et de fraîcheur, pour un parfum longue durée qui vous accompagne toute la journée. Flacon élégant et solide, design luxueux. Disponible en plusieurs tailles (50 à 200 ml).', 'قوة الرجل: جاذبية وأناقة وإغراء. مزيج راقٍ من الخشب والتوابل والانتعاش، بعطر يدوم طوال اليوم. زجاجة أنيقة ومتينة بتصميم فاخر. متوفر بعدة أحجام (من 50 إلى 200 مل).', 'img/products/hawas-fire.webp', 0),
  ('juicy-couture-majestic-woods', 'perfume', 'Juicy Couture — Majestic Woods (Eau de Parfum)', 'جوسي كوتور — ماجستيك وودز (ماء عطر)', 16000, 2, 'L''élégance au naturel. Un mélange raffiné de bois précieux, de fleurs et de musc, pour un parfum longue durée. Flacon élégant et solide, design luxueux et intemporel signé Juicy Couture. Disponible en plusieurs formats (30 à 200 ml).', 'الأناقة بكل عفوية. مزيج راقٍ من الأخشاب الثمينة والزهور والمسك بعطر يدوم طويلًا. زجاجة أنيقة بتصميم فاخر وخالد من جوسي كوتور. متوفر بعدة أحجام (من 30 إلى 200 مل).', 'img/products/juicy-couture-majestic-woods.webp', 1),
  ('givenchy-pour-homme', 'perfume', 'Givenchy Pour Homme — Eau de Toilette', 'جيفنشي بور أوم — ماء تواليت', 16000, 2, 'Une fragrance intemporelle pour l''homme moderne et raffiné, élégante et sensuelle. Notes de tête : bergamote, citron, lavande. Notes de cœur : épices, fleurs d''iris, cèdre. Notes de fond : bois de santal, vétiver, musc. Un classique pour toutes les occasions.', 'عطر خالد للرجل العصري الراقي، أنيق وحسّي. النوتات العليا: برغموت وليمون ولافندر. نوتات القلب: توابل وزهر السوسن وأرز. نوتات القاعدة: خشب الصندل وفيتيفر ومسك. كلاسيكي لكل المناسبات.', 'img/products/givenchy-pour-homme.webp', 2),
  ('prada-luna-rossa', 'perfume', 'Prada Luna Rossa — Le Parfum (Eau de Parfum)', 'برادا لونا روسا — لو بارفان (ماء عطر)', 21000, 2, 'Une fragrance intense, entre fraîcheur et élégance, inspirée de l''univers de la mer et de la haute performance. Notes de tête : agrumes, lavande, menthe. Cœur : accords aquatiques, sauge. Fond : bois de cèdre, ambre, vanille. 100 ml.', 'عطر قوي بين الانتعاش والأناقة، مستوحى من عالم البحر والأداء العالي. النوتات العليا: حمضيات ولافندر ونعناع. القلب: أكوردات مائية ومريمية. القاعدة: خشب الأرز والعنبر والفانيليا. 100 مل.', 'img/products/prada-luna-rossa.webp', 3),
  ('chopard-leather-malaki', 'perfume', 'Chopard Leather Malaki — Eau de Parfum', 'شوبارد ليذر ملاكي — ماء عطر', 15000, 2, 'Une fragrance puissante et raffinée : boisée, épicée et cuirée, conçue pour l''homme moderne et élégant. Notes de tête : bergamote, épices, poivre noir. Cœur : cuir, bois de cèdre, lavande. Fond : ambre, vanille, patchouli. Disponible en 100 ml.', 'عطر قوي وراقٍ: خشبي وتوابلي وجلدي، مصمم للرجل العصري الأنيق. النوتات العليا: برغموت وتوابل وفلفل أسود. القلب: جلد وخشب الأرز ولافندر. القاعدة: عنبر وفانيليا وباتشولي. متوفر بحجم 100 مل.', 'img/products/chopard-leather-malaki.webp', 4),
  ('jean-lowe-azure', 'perfume', 'Jean Lowe Azure — Maison Alhambra (Eau de Parfum)', 'جان لو أزور — ميزون الحمراء (ماء عطر)', 9000, 2, 'Une fraîcheur intense au charme élégant, pour l''homme moderne. Notes aquatiques et aromatiques pour une sensation de liberté et de bien-être. Tête : bergamote, citron, notes marines. Cœur : lavande, romarin, notes aromatiques. Fond : bois de cèdre, bois ambré, musc. 100 ml.', 'انتعاش قوي بسحر أنيق للرجل العصري. نوتات مائية وعطرية تمنحك إحساسًا بالحرية والراحة. العليا: برغموت وليمون ونوتات بحرية. القلب: لافندر وإكليل الجبل. القاعدة: خشب الأرز والخشب العنبري والمسك. 100 مل.', 'img/products/jean-lowe-azure.webp', 5),
  ('ck-free', 'perfume', 'Calvin Klein CK Free For Men — Eau de Toilette', 'كالفن كلاين سي كي فري للرجال — ماء تواليت', 10500, 2, 'L''expression d''une liberté au masculin. Une fragrance moderne et énergisante qui allie fraîcheur, énergie et sensualité. Fraîcheur naturelle, notes aquatiques et boisées, longue tenue toute la journée. Idéal pour toutes les occasions : travail, sorties, quotidien. 100 ml.', 'تعبير عن الحرية بروح رجولية. عطر عصري ومنشّط يجمع الانتعاش والطاقة والحسّية. انتعاش طبيعي ونوتات مائية وخشبية وثبات طوال اليوم. مناسب لكل المناسبات. 100 مل.', 'img/products/ck-free.webp', 6),
  ('dior-addict', 'perfume', 'Dior Addict — Eau de Parfum', 'ديور أدكت — ماء عطر', 25000, 2, 'Une fragrance iconique pour une femme unique : une invitation à la liberté. Un sillage intense et sensuel où le jasmin éclatant rencontre la vanille envoûtante et des bois précieux. Une fragrance moderne, féminine et addictive, comme un coup de cœur.', 'عطر أيقوني لامرأة فريدة: دعوة إلى الحرية. أثر قوي وحسّي يلتقي فيه الياسمين المتألق بالفانيليا الساحرة والأخشاب الثمينة. عطر عصري وأنثوي وإدماني، كحبٍّ من أول نظرة.', 'img/products/dior-addict.webp', 7),
  ('bois-imperial', 'perfume', 'Essential Parfums — Bois Impérial by Quentin Bisch (Eau de Parfum)', 'إسنشيال بارفان — بوا إمبريال من كوينتن بيش (ماء عطر)', 31000, 2, 'Une fragrance boisée et épicée, puissante et raffinée. La chaleur des épices et la force du bois de cèdre rencontrent la douceur de la fève tonka. Flacon rechargeable et durable, 83 % d''ingrédients d''origine naturelle, création française exigeante. 100 ml.', 'عطر خشبي وتوابلي، قوي وراقٍ. دفء التوابل وقوة خشب الأرز يلتقيان بنعومة فول التونكا. زجاجة قابلة لإعادة التعبئة ومتينة، 83٪ من مكوناتها من أصل طبيعي، إبداع فرنسي. 100 مل.', 'img/products/bois-imperial.webp', 8),
  ('portefeuille-cuir-compact', 'leather', 'Portefeuille en cuir compact', 'محفظة جلد مدمجة', 2500, 1, 'L''élégance dans la plus petite taille. En cuir véritable doux au toucher et résistant : plusieurs rangements pour cartes, emplacement billets et porte-monnaie à fermeture élégante et solide. Disponible en 4 couleurs : rouge, marron, noir, bleu marine.', 'الأناقة في أصغر حجم. من الجلد الطبيعي الناعم والمتين: عدة أماكن للبطاقات ومكان للأوراق النقدية وجيب للنقود بإغلاق أنيق ومتين. متوفرة بـ 4 ألوان: أحمر وبني وأسود وأزرق داكن.', 'img/products/portefeuille-cuir-compact.webp', 9),
  ('westpolo-portefeuille', 'leather', 'Westpolo — Portefeuille en cuir', 'ويست بولو — محفظة جلد', 4500, 1, 'Un accessoire indispensable pour un style raffiné au quotidien. 100 % cuir véritable, doux au toucher et résistant ; compartiments multiples pour cartes, billets, pièces et documents ; coutures renforcées. Disponible en plusieurs couleurs : marron, noir, bleu, camel, rouge.', 'إكسسوار لا غنى عنه لأسلوب راقٍ كل يوم. جلد طبيعي 100٪ ناعم ومتين؛ أقسام متعددة للبطاقات والأوراق النقدية والقطع النقدية والوثائق؛ خياطة مدعّمة. متوفرة بعدة ألوان: بني وأسود وأزرق وكاميل وأحمر.', 'img/products/westpolo-portefeuille.webp', 10),
  ('kemei-grooming', 'care', 'Kemei Professional Grooming', 'كيمي — أدوات العناية بالمظهر', 5000, 1, 'Un style impeccable à tout moment. Lames en acier inoxydable (précision et durabilité), batterie longue durée (jusqu''à 90 min), recharge USB, faible bruit, design ergonomique. Disponible en plusieurs types — tondeuse cheveux, tondeuse barbe, rasoir électrique, tondeuse nez/oreilles — et en plusieurs couleurs.', 'مظهر مثالي في كل وقت. شفرات من الفولاذ المقاوم للصدأ (دقة ومتانة)، بطارية طويلة المدى (حتى 90 دقيقة)، شحن USB، هدوء في الاستعمال، تصميم مريح. متوفر بعدة أنواع — ماكينة شعر، ماكينة لحية، شفرة كهربائية، ماكينة أنف وأذن — وبعدة ألوان.', 'img/products/kemei-grooming.webp', 11),
  ('boss-bottled-deo', 'care', 'Hugo Boss Bottled — Déodorant stick', 'هوغو بوس بوتلد — مزيل عرق ستيك', 4500, 1, 'Une fraîcheur élégante tout au long de la journée. Protection anti-odeurs longue durée, sans alcool (respecte la peau), parfum iconique Boss Bottled, séchage rapide, douceur sur la peau. 75 ml / 70 g. Idéal pour tous les jours et en déplacement.', 'انتعاش أنيق طوال اليوم. حماية طويلة المدى من الروائح، خالٍ من الكحول (لطيف على البشرة)، عطر Boss Bottled الشهير، جفاف سريع ونعومة على البشرة. 75 مل / 70 غ. مناسب كل يوم وللسفر.', 'img/products/boss-bottled-deo.webp', 12),
  ('juice-power-bank', 'accessory', 'Juice Power Bank', 'جويس — شاحن متنقل', 5000, 1, 'Toujours avec vous ! Charge rapide pour un gain de temps au quotidien, ports multiples (USB-A / USB-C selon modèle), protection intelligente contre la surchauffe et les courts-circuits, design compact facile à transporter. Disponible en plusieurs capacités (5 000 à 20 000 mAh) et plusieurs couleurs.', 'دائمًا معك! شحن سريع يوفّر وقتك، منافذ متعددة (USB-A / USB-C حسب الطراز)، حماية ذكية من السخونة الزائدة والدارات القصيرة، تصميم مدمج سهل الحمل. متوفر بعدة سعات (من 5000 إلى 20000 مللي أمبير) وعدة ألوان.', 'img/products/juice-power-bank.webp', 13),
  ('montre-poedagar', 'watch', 'Montre femme Poedagar', 'ساعة نسائية بويداغار', 5000, 1, 'L''élégance au poignet, le temps en plus. Une montre au design raffiné et intemporel, pensée pour sublimer chaque instant. Son cadran minimaliste et son bracelet en acier inoxydable en font un accessoire à la fois chic, moderne et durable. Mouvement quartz précis.', 'الأناقة على المعصم، والوقت بين يديك. ساعة بتصميم راقٍ وخالد لتزيّن كل لحظة. مينا بسيط وسوار من الفولاذ المقاوم للصدأ يجعلانها أنيقة وعصرية ومتينة. حركة كوارتز دقيقة.', 'img/products/montre-poedagar.webp', 14),
  ('montre-ikea', 'watch', 'Montre femme IKEA', 'ساعة نسائية IKEA', 4500, 1, 'Une touche de raffinement à chaque instant. Simplicité et élégance dans un design intemporel ; son bracelet bicolore apporte une touche moderne et féminine, parfaite pour sublimer vos tenues. Mouvement quartz précis, acier inoxydable haute qualité. Deux variantes : or & argent, argent.', 'لمسة رقيّ في كل لحظة. بساطة وأناقة بتصميم خالد؛ سوارها ثنائي اللون يمنحها لمسة عصرية وأنثوية تناسب كل إطلالة. حركة كوارتز دقيقة وفولاذ عالي الجودة. نسختان: ذهبي وفضي، وفضي.', 'img/products/montre-ikea.webp', 15),
  ('foulard-soie', 'scarf', 'Foulard en soie Signature — Élégance au quotidien', 'وشاح حرير سيغنتشر — أناقة يومية', 2000, 1, 'Un accessoire intemporel pour toutes vos envies. En soie naturelle, ce foulard allie douceur, légèreté et raffinement. Plusieurs couleurs et thèmes au choix (équestre, floral, géométrique, chaînes). Finitions soignées de haute qualité. Idéal pour toutes les occasions.', 'إكسسوار خالد لكل رغباتك. من الحرير الطبيعي، يجمع هذا الوشاح بين النعومة والخفة والرقي. عدة ألوان وأنماط للاختيار (فروسية، زهور، هندسي، سلاسل). تشطيبات عالية الجودة. مناسب لكل المناسبات.', 'img/products/foulard-soie.webp', 16),
  ('kamiss-homme', 'clothing', 'Kamiss Homme', 'قميص رجالي تقليدي (كميس)', 7500, 3, 'Confort, élégance et authenticité. Un vêtement traditionnel revisité pour l''homme moderne, confectionné avec des tissus de qualité pour allier confort, élégance et distinction, pour toutes les occasions. Tissu doux et respirant, finition soignée. Plusieurs couleurs et tailles (S à XXXL).', 'راحة وأناقة وأصالة. لباس تقليدي بروح عصرية للرجل، مصنوع من أقمشة عالية الجودة تجمع الراحة والأناقة والتميّز لكل المناسبات. قماش ناعم ومريح وتشطيب متقن. عدة ألوان ومقاسات (من S إلى XXXL).', 'img/products/kamiss-homme.webp', 17),
  ('manuka-honey', 'gourmet', 'Manuka Honey Multifloral (MGO 100+)', 'عسل مانوكا متعدد الأزهار (MGO 100+)', 5000, 1, 'Un concentré de nature, pour votre bien-être. Récolté en Nouvelle-Zélande, le miel de Manuka est reconnu pour sa richesse naturelle en MGO (méthylglyoxal), ses propriétés antibactériennes et ses vertus exceptionnelles. 100 % naturel et pur, riche en enzymes et en antioxydants, il soutient l''immunité.', 'خلاصة الطبيعة لعافيتك. يُجنى عسل مانوكا في نيوزيلندا ويشتهر بغناه الطبيعي بمادة MGO (الميثيل غليوكسال) وخصائصه المضادة للبكتيريا وفوائده الاستثنائية. طبيعي ونقي 100٪، غني بالإنزيمات ومضادات الأكسدة، يدعم المناعة.', 'img/products/manuka-honey.webp', 18),
  ('thermos-signature', 'lifestyle', 'Thermos Signature', 'ترمس سيغنتشر', 1800, 1, 'Fièrement au quotidien : l''allié parfait pour rester hydraté avec style, partout. Isolation thermique (garde vos boissons chaudes ou fraîches plus longtemps), acier inoxydable de qualité sans BPA, étanche et sécurisé. Pratique au bureau, en voyage et au sport. Plusieurs formes et couleurs.', 'بفخر كل يوم: رفيقك المثالي لترطيب يومك بأناقة أينما كنت. عزل حراري (يحافظ على مشروباتك ساخنة أو باردة لوقت أطول)، فولاذ مقاوم للصدأ عالي الجودة وخالٍ من BPA، محكم ومؤمَّن. عملي في المكتب والسفر والرياضة. عدة أشكال وألوان.', 'img/products/thermos-signature.webp', 19);
insert into public.box_options (code, type, name_fr, name_ar, description_fr, description_ar, price, capacity, hex, sort) values
  ('small', 'size', 'Petite', 'صغيرة', 'Signature Essentielle', 'Signature Essentielle', 2500, 4, '', 0),
  ('medium', 'size', 'Moyenne', 'متوسطة', 'Signature Élégance', 'Signature Élégance', 3500, 6, '', 1),
  ('large', 'size', 'Grande', 'كبيرة', 'Signature Prestige', 'Signature Prestige', 5000, 8, '', 2),
  ('simili', 'material', 'Simili cuir', 'جلد صناعي (سيميلي)', '', '', 0, null, '', 0),
  ('forex', 'material', 'Forex laqué', 'فوريكس مطلي (لاكيه)', '', '', 0, null, '', 1);
insert into public.box_options (code, type, name_fr, name_ar, price, hex, sort, material_id)
insert into public.collections (code, name_fr, name_ar, tagline_fr, tagline_ar, image_url, kind, ref, sort) values
  ('essentielle', 'Signature Essentielle', 'Signature Essentielle', 'Petite box · jusqu''à 4 cases', 'صندوق صغير · حتى 4 خانات', 'img/col-orchidee.jpg', 'size', 'small', 0),
  ('elegance', 'Signature Élégance', 'Signature Élégance', 'Moyenne box · jusqu''à 6 cases', 'صندوق متوسط · حتى 6 خانات', 'img/col-elegance.jpg', 'size', 'medium', 1),
  ('prestige', 'Signature Prestige', 'Signature Prestige', 'Grande box · jusqu''à 8 cases', 'صندوق كبير · حتى 8 خانات', 'img/col-prestige.jpg', 'size', 'large', 2),
  ('vip-man', 'Signature VIP Corporate Man', 'Signature VIP Corporate Man', 'Cadeaux d''affaires pour lui · sur devis', 'هدايا أعمال للرجال · حسب الطلب', 'img/col-vip-homme.jpg', 'quote', 'vip-man', 3),
  ('vip-woman', 'Signature VIP Corporate Woman', 'Signature VIP Corporate Woman', 'Cadeaux d''affaires pour elle · sur devis', 'هدايا أعمال للنساء · حسب الطلب', 'img/col-vip-femme.jpg', 'quote', 'vip-woman', 4),
  ('bespoke', 'Signature Bespoke', 'Signature Bespoke', 'Votre coffret entièrement sur mesure · sur devis', 'صندوقك بالكامل حسب الطلب · حسب العرض', 'img/col-algeria.jpg', 'quote', 'bespoke', 5);
