-- =====================================================================
-- SIGNATURE — catalogue initial (20 articles du catalogue 01, options de box, 6 collections)
-- À exécuter UNE SEULE FOIS dans Supabase > SQL Editor (APRÈS schema.sql).
-- ⚠ Il REMPLACE les anciens produits / options / collections d'exemple. Les commandes ne sont pas touchées.
-- =====================================================================

delete from public.collections;
delete from public.products;
delete from public.box_options;



select v.code, 'color', v.name_fr, v.name_ar, 0, v.hex, v.sort, (select id from public.box_options where type='material' and code = v.mat) from (values
  ('noir', 'Noir', 'أسود', '#17120f', 0, 'simili'),
  ('marron', 'Marron', 'بني', '#4b2e20', 1, 'simili'),
  ('blanc', 'Blanc', 'أبيض', '#f4f1ea', 2, 'forex'),
  ('vert-sauge', 'Vert sauge', 'أخضر مريمي', '#8c9c85', 3, 'forex'),
  ('bordeaux', 'Bordeaux', 'بوردو', '#5b1e2b', 4, 'forex')
) as v(code, name_fr, name_ar, hex, sort, mat);


notify pgrst, 'reload schema';
